\documentclass[11pt]{article}
\usepackage[margin=2.5cm]{geometry}

\title{Recovery of a Restored Reed Bed After the 2023 Dieback Event}
\author{M. Lindqvist and P. Okafor}
\date{March 2026}

\begin{document}
\maketitle

\section{Introduction}
The Hjalmaren pilot wetland was replanted in spring 2021 as part of
the shoreline restoration programme. A partial dieback of the reed
stand in the hot summer of 2023 raised concerns that the planting
stock had failed, and this note summarises the follow-up monitoring
through the 2025 season.

\section{Methods}
Stem density was recorded in late June of each year along the three
permanent transects established at planting. Each transect was sampled
at ten stations, and all rooted stems within a 0.25~m$^2$ quadrat were
counted. Water level and conductivity were logged continuously at the
inlet weir.

\begin{figure}[h]
\centering
\fbox{\rule{0pt}{5cm}\rule{8cm}{0pt}}
\caption{Stem density of \emph{Phragmites australis}\footnote{Counted
along three 25~m transects with ten quadrats each.} recovered to
pre-dieback levels by the 2025 season.}
\label{fig:density}
\end{figure}

\section{Results}
Mean stem density fell from 214 stems/m$^2$ in 2022 to 96 stems/m$^2$
after the dieback, then rose to 187 stems/m$^2$ in 2024 and
231 stems/m$^2$ in 2025 (Figure~\ref{fig:density}). Recovery was
fastest at the shallow end of each transect, where rhizome mortality
had been lowest. Conductivity stayed below the tolerance threshold
throughout, so salinity intrusion is not implicated in the dieback.

\section{Discussion}
The trajectory supports the hypothesis that the 2023 event was heat
stress rather than planting failure. We recommend continuing the
transect monitoring for two more seasons and extending the quadrat
grid to the western cell, which was replanted a year later.

\end{document}

